import re

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}


def _field(row, key):
    """Return a field as a stripped string, treating missing or None as empty."""
    return (row.get(key) or "").strip()


def _normalize_email(raw):
    """Return the normalized valid email, or None if it is not valid."""
    email = (raw or "").strip().lower()
    if email.count("@") != 1:
        return None
    local, domain = email.split("@")
    if domain in _GMAIL_DOMAINS:
        local = local.replace(".", "")
        local = local.split("+", 1)[0]
        domain = "gmail.com"
    if not local:
        return None
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return None
    return f"{local}@{domain}"


def _normalize_phone(raw):
    """Return the normalized 10-digit phone, or None if it is not valid."""
    digits = re.sub(r"[^0-9]", "", raw or "")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits if len(digits) == 10 else None


def _normalize_tags(raw):
    """Return the set of stripped, lowercased, non-empty tags from a semicolon-separated string."""
    return {t.strip().lower() for t in (raw or "").split(";") if t.strip()}


def _most_recent_value(ordered, getter):
    """Return the value from the first member of `ordered` (most recent first) that yields a non-empty value."""
    for member in ordered:
        value = getter(member)
        if value:
            return value
    return ""


def dedupe_contacts(rows):
    # Steps 1-4: normalize fields and drop rows with no valid email or phone.
    records = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        phone = _normalize_phone(row.get("phone", ""))
        if email is None and phone is None:
            continue
        records.append({
            "idx": idx,
            "row": row,
            "email": email,
            "phone": phone,
            "last_key": _field(row, "last_name").lower(),
            "updated": _field(row, "updated"),
        })

    # Step 5: group rows with union-find so matches are transitive.
    parent = list(range(len(records)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_by_email = {}
    first_by_phone_last = {}
    for r, rec in enumerate(records):
        if rec["email"] is not None:
            if rec["email"] in first_by_email:
                union(first_by_email[rec["email"]], r)
            else:
                first_by_email[rec["email"]] = r
        if rec["phone"] is not None and rec["last_key"]:
            key = (rec["phone"], rec["last_key"])
            if key in first_by_phone_last:
                union(first_by_phone_last[key], r)
            else:
                first_by_phone_last[key] = r

    # Collect groups. Records are in input order, so dict insertion order
    # reflects each person's earliest row.
    groups = {}
    for r in range(len(records)):
        groups.setdefault(find(r), []).append(records[r])

    # Steps 6-7: build one output dict per person.
    output = []
    for members in groups.values():
        # Most recently updated first; ties keep input order (stable sort).
        ordered = sorted(members, key=lambda m: m["idx"])
        ordered.sort(key=lambda m: m["updated"], reverse=True)

        all_tags = set()
        opted_out = "N"
        for m in members:
            all_tags |= _normalize_tags(m["row"].get("tags", ""))
            if _field(m["row"], "opted_out").upper() == "Y":
                opted_out = "Y"

        output.append({
            "first_name": _most_recent_value(ordered, lambda m: _field(m["row"], "first_name")),
            "last_name": _most_recent_value(ordered, lambda m: _field(m["row"], "last_name")),
            "email": _most_recent_value(ordered, lambda m: m["email"]),
            "phone": _most_recent_value(ordered, lambda m: m["phone"]),
            "zip": _most_recent_value(ordered, lambda m: _field(m["row"], "zip")),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": opted_out,
            "updated": ordered[0]["updated"],
        })

    return output
```

Notes on implementation choices:

- **Email validity is checked after normalization.** For example, `+news@gmail.com` normalizes to an empty local part and is treated as invalid.
- **Phone-based matching requires a non-empty last name on both rows.** Email-based matching does not check last name, per the rules.
- **Tie-breaking on `updated` uses a stable sort.** Rows with equal dates keep their input order. `updated` is compared as a string, which works for ISO dates.
- **Opt-outs are merged across the whole group.** If any duplicate row is marked "Y", the person is output as opted out, so a stale duplicate can't re-subscribe someone who opted out.

